      "detail": "{\n  \"schemaVersion\": \"1.0\",\n  \"uid\": \"01M7GTBMQT-H66V\",\n  \"type\": \"requirement_group\",\n  \"name\": \"Public Web Infrastructure & Edge Proxy Requirements\",\n  \"description\": \"Governed requirement group defining mandatory architectural requirements and acceptable use policy for public web services and endpoints.\",\n  \"version\": \"1.1.0\",\n  \"catalogStatus\": \"complete\",\n  \"lifecycleStatus\": \"preferred\",\n  \"activation\": \"always\",\n  \"appliesTo\": [\n    \"software_deployment_pattern\",\n    \"product_component\",\n    \"network_service\"\n  ],\n  \"authority\": {\n    \"name\": \"Geordi (Chief Engineer)\",\n    \"shortName\": \"Geordi\",\n    \"source\": \"Skippy Submind Architecture Governance\"\n  },\n  \"owner\": {\n    \"team\": \"engineering-platform\",\n    \"contact\": \"dale.sackrider+geordi@gmail.com\"\n  },\n  \"acceptableUsePolicy\": {\n    \"mandatory\": true,\n    \"policy\": \"All public web endpoints across Submind and client workloads MUST be fronted by Cloudflare Global Anycast Edge Proxy ($0 Free Tier). Bare GHS CNAME mappings and unproxied origin endpoints are strictly non-compliant.\"\n  },\n  \"requirements\": [\n    {\n      \"id\": \"req-edge-proxy-mandatory\",\n      \"description\": \"Every public website or web service MUST be fronted by an External Anycast Edge Proxy Service (Cloudflare Free Tier or compliant Managed Edge Proxy). Direct bare host mappings (such as ghs.googlehosted.com) without ALPN-compliant edge TLS proxying are strictly prohibited.\",\n      \"canBeSatisfiedBy\": [\n        {\n          \"mechanism\": \"field\",\n          \"key\": \"networkService\"\n        },\n        {\n          \"mechanism\": \"decisionRecord\",\n          \"key\": \"edgeProxyDecision\"\n        }\n      ],\n      \"minimumSatisfactions\": 1,\n      \"requirementMode\": \"mandatory\",\n      \"naAllowed\": false,\n      \"validAnswerTypes\": [\n        \"field\",\n        \"decisionRecord\"\n      ]\n    }\n  ],\n  \"_source\": \"configurations/requirement-groups/requirement-group-edge-networking-standards.yaml\"\n}",
      "existsInCatalog": true,
